CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS public.profiles (id uuid PRIMARY KEY, username text UNIQUE, email text UNIQUE, full_name text, role text NOT NULL DEFAULT 'student', created_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON tc.constraint_name=kcu.constraint_name AND tc.constraint_schema=kcu.constraint_schema WHERE tc.constraint_type='FOREIGN KEY' AND tc.table_schema='public' AND tc.table_name='profiles' AND kcu.column_name='id') THEN ALTER TABLE public.profiles ADD CONSTRAINT profiles_auth_users_fk FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE; END IF; END $$;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS username text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS email text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role text NOT NULL DEFAULT 'student'; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
CREATE UNIQUE INDEX IF NOT EXISTS profiles_username_unique_idx ON public.profiles (username); CREATE UNIQUE INDEX IF NOT EXISTS profiles_email_unique_idx ON public.profiles (email); ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS profiles_is_owner ON public.profiles; CREATE POLICY profiles_is_owner ON public.profiles FOR SELECT USING (auth.uid() = id);
DROP POLICY IF EXISTS profiles_insert_own ON public.profiles; CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);
DROP POLICY IF EXISTS profiles_update_own ON public.profiles; CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE OR REPLACE FUNCTION public.create_auth_profile() RETURNS trigger AS $$ BEGIN INSERT INTO public.profiles (id,email,username,full_name,role,created_at) VALUES (NEW.id,NEW.email,COALESCE(NEW.raw_user_meta_data->>'username',split_part(NEW.email,'@',1)),NEW.raw_user_meta_data->>'full_name','student',now()) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER;
DROP TRIGGER IF EXISTS auth_user_profile_insert ON auth.users; CREATE TRIGGER auth_user_profile_insert AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_auth_profile();
